async fn remote_status_after_reopen_is_disabled_session_only() {
    let dir = TempDir::new().expect("tempdir");
    let config_path = dir.path().join("remote-config.json");
    let auth_path = dir.path().join("remote-auth.json");
    std::fs::write(
        &config_path,
        r#"{"mode":"localNetwork","port":45678,"allowControl":false}"#,
    )
    .expect("write stale enabled config");

    let terminal = Arc::new(TerminalService::default());
    let registry = WorkspaceRegistry::new();
    let first = RemoteGatewayState::new_with_paths(
        Arc::clone(&terminal),
        registry.clone(),
        Some(config_path.clone()),
        Some(auth_path.clone()),
    );
    first.config.write().mode = RemoteNetworkMode::LocalNetwork;
    first.config.write().port = 45678;
    first.config.write().allow_control = false;
    first.persist_config().expect("persist enabled session");

    let reopened = Arc::new(RemoteGatewayState::new_with_paths(
        terminal,
        registry,
        Some(config_path),
        Some(auth_path),
    ));
    let app = tauri::test::mock_builder()
        .manage(Arc::new(RemoteGatewayManager::new(reopened)))
        .build(tauri::test::mock_context(tauri::test::noop_assets()))
        .expect("mock app");

    let status = cmd_remote_status(app.state()).await.expect("status");
    assert!(
        !status.enabled,
        "relaunch must not report an active listener"
    );
    assert_eq!(status.mode, RemoteNetworkMode::Off);
    assert_eq!(status.port, 45678);
    assert!(status.bound_address.is_none());
    assert_eq!(status.restart_policy, RemoteRestartPolicy::SessionOnly);
}

#[test]
fn terminal_process_cwd_resolves_accurately() {
    let current_pid = std::process::id();
    let resolved = process_cwd(current_pid);
    assert!(resolved.is_some(), "process_cwd should resolve current pid");
    let resolved_path = resolved.expect("resolved path");
    assert!(resolved_path.exists());
    let current_dir = std::env::current_dir().expect("current dir");
    assert_eq!(
        resolved_path.canonicalize().expect("canonicalize resolved"),
        current_dir
            .canonicalize()
            .expect("canonicalize current dir")
    );
}

